sp_widget.client_script:
api.controller = function() {

    var c = this;


    // =====================================================
    // SEARCH
    // =====================================================

    c.searchQuery = "";


    // =====================================================
    // SEARCH FILTER
    // =====================================================

    c.filterAttention = function(item) {

        if (!c.searchQuery) {

            return true;

        }


        var search =
            String(
                c.searchQuery
            ).toLowerCase();


        var student =
            String(
                item.student_name || ""
            ).toLowerCase();


        var studentId =
            String(
                item.student_id || ""
            ).toLowerCase();


        var caseId =
            String(
                item.case_id || ""
            ).toLowerCase();


        var visa =
            String(
                item.visa_type || ""
            ).toLowerCase();


        var issue =
            String(
                item.issue || ""
            ).toLowerCase();


        var status =
            String(
                item.status || ""
            ).toLowerCase();


        var risk =
            String(
                item.risk || ""
            ).toLowerCase();


        return (
            student.indexOf(search) !== -1 ||
            studentId.indexOf(search) !== -1 ||
            caseId.indexOf(search) !== -1 ||
            visa.indexOf(search) !== -1 ||
            issue.indexOf(search) !== -1 ||
            status.indexOf(search) !== -1 ||
            risk.indexOf(search) !== -1
        );

    };


    // =====================================================
    // REFRESH DATA
    // =====================================================

    c.refresh = function() {

        c.server.update();

    };

};

