// CHECK CURRENT LOGIN
// =====================================================

if (gs.isLoggedIn() && gs.getUserName() != "guest") {

    var currentUserId = gs.getUserID();

    var studentProfile =
        new GlideRecord("x_snc_visaguardi_0_student_profile");

    studentProfile.addQuery("user", currentUserId);
    studentProfile.setLimit(1);
    studentProfile.query();

    if (studentProfile.next()) {

        data.userExists = true;

    } else {

        // Fallback: search by User ID
        var currentUser =
            new GlideRecord("sys_user");

        if (currentUser.get(currentUserId)) {

            var profileByUsername =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );

            profileByUsername.addQuery(
                "user_name",
                currentUser.getValue("user_name")
            );

            profileByUsername.setLimit(1);
            profileByUsername.query();

            if (profileByUsername.next()) {
                data.userExists = true;
            }
        }
    }
}


// =====================================================
// LOGIN SUBMISSION
// =====================================================

if (
    input &&
    input.username &&
    input.password
) {

    var username =
        String(input.username).trim();

    var password =
        String(input.password);


    // =================================================
    // FIND USER BY USERNAME OR EMAIL
    // =================================================

    var userGr =
        new GlideRecord("sys_user");


    // IMPORTANT:
    // Use GlideQueryCondition for OR
    var condition =
        userGr.addQuery(
            "user_name",
            username
        );

    condition.addOrCondition(
        "email",
        username
    );


    // Only active users
    userGr.addQuery(
        "active",
        true
    );

    userGr.setLimit(1);

    userGr.query();


    // =================================================
    // USER NOT FOUND
    // =================================================

    if (!userGr.next()) {

        data.login_success = false;

        data.login_error =
            "User ID or Email not found.";

        return;
    }


    // =================================================
    // USER INFORMATION
    // =================================================

    var actualUsername =
        userGr.getValue("user_name");

    var userSysId =
        userGr.getUniqueValue();


    // =================================================
    // CHECK STUDENT PROFILE
    // =================================================

    var profile =
        new GlideRecord(
            "x_snc_visaguardi_0_student_profile"
        );

    var profileFound = false;


    // -------------------------------------------------
    // OPTION 1: USER REFERENCE
    // -------------------------------------------------

    profile.addQuery("user", userSysId);
    profile.setLimit(1);
    profile.query();

    if (profile.next()) {

        profileFound = true;
    }


    // -------------------------------------------------
    // OPTION 2: USER NAME
    // -------------------------------------------------

    if (!profileFound) {

        profile =
            new GlideRecord(
                "x_snc_visaguardi_0_student_profile"
            );

        profile.addQuery(
            "user_name",
            actualUsername
        );

        profile.setLimit(1);

        profile.query();

        if (profile.next()) {

            profileFound = true;
        }
    }


    // =================================================
    // PROFILE DOES NOT EXIST
    // =================================================

    if (!profileFound) {

        data.login_success = false;

        data.login_error =
            "Student profile was not found for this account.";

        return;
    }
// =================================================
// PASSWORD AUTHENTICATION
// =================================================

try {

if (typeof global.ScopedLoginHelper !== "function") {

    data.login_success = false;

    data.login_error =
        "Login helper is not available. Please check ScopedLoginHelper Script Include.";

    gs.error(
        "VisaGuardian Login Error: ScopedLoginHelper Script Include is not available."
    );

    return;
}

var authHelper =
    new global.ScopedLoginHelper();

if (typeof authHelper.login !== "function") {

    data.login_success = false;

    data.login_error =
        "Login method is not available in ScopedLoginHelper.";

    gs.error(
        "VisaGuardian Login Error: login() method is missing in ScopedLoginHelper."
    );

    return;
}

var authenticated =
    authHelper.login(
        actualUsername,
        password
    );


// =================================================
// SUCCESS
// =================================================

if (authenticated === true) {

    gs.getSession().putClientData(
"vg_student_sys_id",
profile.getUniqueValue()
);

gs.getSession().putClientData(
"vg_student_user_name",
profile.getValue("user_name")
);
data.login_success = true;

    data.login_error = "";

    data.redirect_url =
        "?id=student_dashboard";

}

// =================================================
// WRONG PASSWORD
// =================================================

else {

    data.login_success = false;

    data.login_error =
        "Invalid password. Please try again.";
}
} catch (ex) {

data.login_success = false;

data.login_error =
    "Unable to authenticate the account: " + ex.message;

gs.error(
    "VisaGuardian Login Error: " +
    ex.message
);
}

}
