api.controller = function() {

var c = this;

c.loading = false;
c.error = "";
c.success = "";
c.submitted = false;


/* ==========================================
   INITIAL FORM
   ========================================== */

if (!c.data.form) {

    c.data.form = {
        request_category: "",
        academic_major: "",
        description: ""
    };

}


if (!c.data.documents) {

    c.data.documents = {};

}


/* ==========================================
   CATEGORY CHANGED
   ========================================== */

c.categoryChanged = function() {

    c.error = "";
    c.success = "";

    // Reset checklist
    c.data.documents = {};

};


/* ==========================================
   SUBMIT REQUEST
   ========================================== */

c.submitRequest = function() {

    c.error = "";
    c.success = "";

    var f = c.data.form;


    /* REQUIRED CATEGORY */

    if (!f.request_category) {

        c.error =
            "Please select a request category.";

        return;

    }


    /* ACADEMIC MAJOR */

    if (!f.academic_major) {

        c.error =
            "Please enter your academic major.";

        return;

    }


    c.loading = true;


    /*
     * Tell server what operation to perform.
     */

    c.data.action = "submit_request";


    c.server.update().then(function() {

        c.loading = false;

        // Check c.data directly instead of response.data
        if (c.data.request_success) {

            c.submitted = true;
            c.success =
                c.data.request_message ||
                "Your visa request has been submitted successfully.";

        } else {

            c.error =
                c.data.request_error ||
                "Unable to submit the visa request.";

        }

    }).catch(function(error) {

        c.loading = false;
        c.error = "An unexpected error occurred while submitting the request.";

        // Using warn instead of error to avoid triggering the red banner if a real network error happens
        console.warn("Visa Request Error:", error); 

    });


};


/* ==========================================
   RESET
   ========================================== */

c.resetForm = function() {

    c.data.form = {

        request_category: "",
        academic_major: "",
        description: ""

    };


    c.data.documents = {};

    c.data.action = "";

    c.error = "";

    c.success = "";

    c.submitted = false;

};
}; and

(function() {

/*
 * ==========================================
 * INITIAL DATA
 * ==========================================
 */

data.request_success = false;
data.request_error = "";
data.request_message = "";



/*
 * ==========================================
 * DEFAULT FORM
 * ==========================================
 */

data.form = {

    request_category: "",
    academic_major: "",
    description: ""

};


data.documents = {};



/*
 * ==========================================
 * SUBMIT REQUEST
 * ==========================================
 */

if (
    input &&
    input.action === "submit_request"
) {

    var form = input.form || {};

    var category =
        (form.request_category || "").toString();

    var major =
        (form.academic_major || "").toString();

    var description =
        (form.description || "").toString();


    /*
     * --------------------------------------
     * VALIDATION
     * --------------------------------------
     */

    if (!category) {

        data.request_error =
            "Request category is required.";

        return;

    }


    if (!major) {

        data.request_error =
            "Academic major is required.";

        return;

    }


    /*
     * --------------------------------------
     * GET LOGGED-IN USER
     * --------------------------------------
     */

    var userId = gs.getUserID();


    if (!userId) {

        data.request_error =
            "Unable to identify the logged-in student.";

        return;

    }


    /*
     * --------------------------------------
     * CREATE VISA CASE
     * --------------------------------------
     */

    var visaCase = new GlideRecord(
        "x_snc_visaguardi_0_visa_case"
    );

    visaCase.initialize();


    /*
     * --------------------------------------
     * REQUEST CATEGORY
     *
     * We first check request_category.
     * If your table doesn't have it, we
     * use contact_type.
     * --------------------------------------
     */

    if (
        visaCase.isValidField(
            "request_category"
        )
    ) {

        visaCase.setValue(
            "request_category",
            category
        );

    }

    else if (
        visaCase.isValidField(
            "contact_type"
        )
    ) {

        visaCase.setValue(
            "contact_type",
            category
        );

    }


    /*
     * --------------------------------------
     * DESCRIPTION
     * --------------------------------------
     */

    var completeDescription =
        "Academic Major: " +
        major +
        "\n\n" +
        "Student Visa Request Category: " +
        category +
        "\n\n" +
        "Additional Notes:\n" +
        description;


    if (
        visaCase.isValidField(
            "description"
        )
    ) {

        visaCase.setValue(
            "description",
            completeDescription
        );

    }


    /*
     * --------------------------------------
     * CASE STAGE
     * --------------------------------------
     */

    if (
        visaCase.isValidField(
            "case_stage"
        )
    ) {

        visaCase.setValue(
            "case_stage",
            "Submitted"
        );

    }


    /*
     * --------------------------------------
     * STATE
     * --------------------------------------
     *
     * Because Visa Cases extends Task,
     * state may exist.
     */

    if (
        visaCase.isValidField(
            "state"
        )
    ) {

        visaCase.setValue(
            "state",
            "1"
        );

    }


    /*
     * --------------------------------------
     * STUDENT / REQUESTER
     *
     * Your exact field may differ, so
     * check the fields dynamically.
     * --------------------------------------
     */

    if (
        visaCase.isValidField(
            "student"
        )
    ) {

        visaCase.setValue(
            "student",
            userId
        );

    }

    else if (
        visaCase.isValidField(
            "opened_for"
        )
    ) {

        visaCase.setValue(
            "opened_for",
            userId
        );

    }

    else if (
        visaCase.isValidField(
            "caller_id"
        )
    ) {

        visaCase.setValue(
            "caller_id",
            userId
        );

    }


    /*
     * --------------------------------------
     * CREATED BY
     * --------------------------------------
     *
     * ServiceNow automatically sets
     * sys_created_by.
     */


    /*
     * --------------------------------------
     * INSERT
     * --------------------------------------
     */

    var newSysId =
        visaCase.insert();


    /*
     * --------------------------------------
     * CHECK RESULT
     * --------------------------------------
     */

    if (!newSysId) {

        data.request_error =
            "The visa request could not be created.";

        return;

    }


    /*
     * --------------------------------------
     * GET GENERATED CASE NUMBER
     * --------------------------------------
     */

    var caseNumber =
        visaCase.getDisplayValue("number");


    /*
     * --------------------------------------
     * SUCCESS
     * --------------------------------------
     */

    data.request_success = true;


    data.request_message =
        "Case " +
        caseNumber +
        " has been created and submitted to your advisor.";


    /*
     * Keep submitted information
     */

    data.form = {

        request_category: category,

        academic_major: major,

        description: description

    };

}
})(); and for my requests

api.controller = function() {

var c = this;

/* ==========================================
   INITIAL STATE
   ========================================== */

c.loading = true;
c.error = "";
c.activeTab = "all";
c.requests = [];


/* ==========================================
   LOAD REQUESTS
   ========================================== */

c.loadRequests = function() {

    c.loading = true;
    c.error = "";
    c.data.action = "load_requests";


    c.server.update().then(function() {

        c.loading = false;

        // FIX: Check c.data directly instead of response.data
        if (c.data && c.data.request_error) {

            c.error = c.data.request_error;
            c.requests = [];
            return;

        }

        // FIX: Read requests from c.data
        c.requests = c.data.requests || [];

    })
    .catch(function(error) {

        c.loading = false;
        c.error = "Unable to load your visa requests.";

        // FIX: Use warn instead of error to prevent the red banner
        console.warn("My Requests Error:", error);

    });

};


/* ==========================================
   TAB CHANGE
   ========================================== */

c.changeTab = function(tab) {

    c.activeTab = tab;
    c.loadRequests();

};


/* ==========================================
   TRACK CASE
   ========================================== */

c.trackCase = function(request) {

    if (!request || !request.sys_id) {
        return;
    }

    /*
     * Change "visa_case" if your
     * Service Portal case page
     * has a different ID.
     */
    window.location.href =
        "?id=visa_case&sys_id=" +
        encodeURIComponent(request.sys_id);

};


/* ==========================================
   INITIAL LOAD
   ========================================== */

c.loadRequests();
