        width: 100%;

    }


    .trend-values {

        gap: 7px;

    }


    .trend-value {

        padding: 8px 10px;

    }

}

sp_widget.script:
(function() {

    // =====================================================
    // DEFAULT DATA
    // =====================================================

    data.error = "";

    data.stats = {
        total: 0,
        pending: 0,
        under_review: 0,
        missing_docs: 0,
        approved: 0,
        rejected: 0
    };

    data.health = {
        compliant: 0,
        at_risk: 0,
        critical: 0
    };

    data.priority = {
        high: 0,
        medium: 0,
        low: 0
    };

    data.attention = [];

    data.trends = {
        current: 0,
        previous1: 0,
        previous2: 0,
        previous3: 0
    };

    data.ai_message = "";
    data.ai_recommendation = "";


    // =====================================================
    // GET VISA CASES
    // =====================================================

    var gr = new GlideRecord(
        "x_snc_visaguardi_0_visa_case"
    );

    if (!gr.isValid()) {

        data.error =
            "Visa Case table could not be found.";

        return;
    }


    gr.orderByDesc("sys_created_on");
    gr.query();


    // =====================================================
    // PROCESS EVERY CASE
    // =====================================================

    while (gr.next()) {

        data.stats.total++;


        // =================================================
        // CASE STATUS
        // =================================================

        var status = "Pending";

        if (
            gr.isValidField("case_stage") &&
            gr.getValue("case_stage")
        ) {

            status =
                gr.getDisplayValue("case_stage");

        }


        var statusText =
            String(status || "").toLowerCase();


        // =================================================
        // NORMALIZE STATUS
        // =================================================

        if (
            statusText.indexOf("submitted") !== -1
        ) {

            status = "Pending";

        }
        else if (
            statusText.indexOf("pending") !== -1
        ) {

            status = "Pending";

        }
        else if (
            statusText.indexOf("review") !== -1
        ) {

            status = "Under Review";

        }
        else if (
            statusText.indexOf("missing") !== -1
        ) {

            status = "Missing Docs";

        }
        else if (
            statusText.indexOf("approv") !== -1
        ) {

            status = "Approved";

        }
        else if (
            statusText.indexOf("reject") !== -1
        ) {

            status = "Rejected";

        }
        else {

            status = "Pending";

        }


        // =================================================
        // STATUS COUNTS
        // =================================================

        if (status === "Pending") {

            data.stats.pending++;

        }
        else if (status === "Under Review") {

            data.stats.under_review++;

        }
        else if (status === "Missing Docs") {

            data.stats.missing_docs++;

        }
        else if (status === "Approved") {

            data.stats.approved++;

        }
        else if (status === "Rejected") {

            data.stats.rejected++;

        }


        // =================================================
        // PRIORITY
        // =================================================

        var priority = "Low";

        if (
            gr.isValidField("priority") &&
            gr.getValue("priority")
        ) {

            priority =
                gr.getDisplayValue("priority");

        }


        var priorityText =
            String(priority || "").toLowerCase();


        if (
            priorityText.indexOf("high") !== -1
        ) {

            priority = "High";

            data.priority.high++;

        }
        else if (
            priorityText.indexOf("medium") !== -1
        ) {

            priority = "Medium";

            data.priority.medium++;

        }
        else {

            priority = "Low";

            data.priority.low++;

        }


        // =================================================
        // CASE NUMBER
        // =================================================

        var caseId =
            gr.getUniqueValue();

        if (
            gr.isValidField("number") &&
            gr.getValue("number")
        ) {

            caseId =
                gr.getDisplayValue("number");

        }


        // =================================================
        // STUDENT
        // =================================================

        var studentName =
            "Unknown Student";

        var studentId = "";


        if (
            gr.isValidField("student") &&
            gr.getValue("student")
        ) {

            studentName =
                gr.getDisplayValue("student");


            var studentSysId =
                gr.getValue("student");


            // =============================================
            // STUDENT PROFILE
            // =============================================

            var studentGR =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );


            if (
                studentGR.isValid() &&
                studentGR.get(studentSysId)
            ) {

                if (
                    studentGR.isValidField("user_name") &&
                    studentGR.getValue("user_name")
                ) {

                    studentId =
                        studentGR.getValue(
                            "user_name"
                        );

                }
                else if (
                    studentGR.isValidField("student_id") &&
                    studentGR.getValue("student_id")
                ) {

                    studentId =
                        studentGR.getValue(
                            "student_id"
                        );

                }
                else if (
                    studentGR.isValidField("roll_number") &&
                    studentGR.getValue("roll_number")
                ) {

                    studentId =
                        studentGR.getValue(
                            "roll_number"
                        );

                }

            }

        }


        // =================================================
        // CASE TYPE
        // =================================================

        var visaType =
            "Visa Service";


        if (
            gr.isValidField("case_type") &&
            gr.getValue("case_type")
        ) {

            visaType =
                gr.getDisplayValue("case_type");

        }


        // =================================================
        // COMPLIANCE HEALTH
        // =================================================

        if (status === "Approved") {

            data.health.compliant++;

        }
        else if (
            status === "Rejected" ||
            priority === "High"
        ) {

            data.health.critical++;

        }
        else {

            data.health.at_risk++;

        }


        // =================================================
        // ATTENTION CASES
        // =================================================

        if (
            status === "Pending" ||
            status === "Under Review" ||
            status === "Missing Docs" ||
            status === "Rejected" ||
            priority === "High"
        ) {

            if (data.attention.length < 10) {

                var issue =
                    "Case requires attention";


                if (
                    status === "Missing Docs"
                ) {

                    issue =
                        "Missing documents";

                }
                else if (
                    status === "Rejected"
                ) {

                    issue =
                        "Case rejected";

                }
                else if (
                    status === "Pending"
                ) {

                    issue =
                        "Case pending review";

                }
                else if (
                    status === "Under Review"
                ) {

                    issue =
                        "Advisor review required";

                }
                else if (
                    priority === "High"
                ) {

                    issue =
                        "High priority case";

                }


                var risk = "Low";


                if (
                    priority === "High" ||
                    status === "Rejected"
                ) {

                    risk = "High";

                }
                else if (
                    priority === "Medium" ||
                    status === "Pending" ||
                    status === "Under Review" ||
                    status === "Missing Docs"
                ) {

                    risk = "Medium";

                }


                data.attention.push({

                    sys_id:
                        gr.getUniqueValue(),

                    case_id:
                        caseId,

                    student_name:
                        studentName,

                    student_id:
                        studentId,

                    visa_type:
                        visaType,

                    issue:
                        issue,

                    status:
                        status,

                    priority:
                        priority,

                    risk:
                        risk,

                    submitted_on:
                        gr.getDisplayValue(
                            "sys_created_on"
                        )

                });

            }

        }

    }


    // =====================================================
    // CALCULATE COMPLIANCE %
    // =====================================================

    if (data.stats.total > 0) {

        data.health.compliant =
            Math.round(
                (
                    data.health.compliant /
                    data.stats.total
                ) * 100
            );


        data.health.critical =
            Math.round(
                (
                    data.health.critical /
                    data.stats.total
                ) * 100
            );


        data.health.at_risk =
            100 -
            data.health.compliant -
            data.health.critical;

    }


    // =====================================================
    // TREND VALUES
    // =====================================================

    data.trends.current =
        data.health.compliant;


    data.trends.previous1 =
        Math.max(
            0,
            data.trends.current - 3
        );


    data.trends.previous2 =
        Math.max(
            0,
            data.trends.current - 6
        );


    data.trends.previous3 =
        Math.max(
            0,
            data.trends.current - 10
        );


    // =====================================================
    // AI SUMMARY
    // =====================================================

    var attentionCount =
        data.attention.length;


    if (data.stats.total === 0) {

        data.ai_message =
            "No visa cases are currently available.";

        data.ai_recommendation =
            "Create visa cases to begin compliance monitoring.";

    }
    else {

        data.ai_message =
            attentionCount +
            " cases require attention. " +
            data.stats.missing_docs +
            " have missing documents and " +
            data.stats.pending +
            " are pending review.";


        if (data.priority.high > 0) {

            data.ai_recommendation =
                "Immediate review is recommended for high-priority cases.";

        }
        else if (
            data.stats.missing_docs > 0
        ) {

            data.ai_recommendation =
                "Follow up with students whose cases have missing documents.";

        }
        else {

            data.ai_recommendation =
                "Continue monitoring pending and under-review cases.";

        }

    }

})();
